#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TagMode {
    Short,
    Medium,
    Long,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SecretKey(pub u64);

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum KeyDecodeError {
    BadPrefix,
    BadLength,
    BadHex,
}

fn tag_len(mode: TagMode) -> usize {
    match mode {
        TagMode::Short => 8,
        TagMode::Medium => 16,
        TagMode::Long => 32,
    }
}

pub fn create_tag(key: &SecretKey, mode: TagMode, message: &[u8]) -> Vec<u8> {
    let mode_word = match mode {
        TagMode::Short => 0x11u64,
        TagMode::Medium => 0x22u64,
        TagMode::Long => 0x44u64,
    };
    let mut state = key.0 ^ mode_word ^ (message.len() as u64).wrapping_mul(0x9e3779b185ebca87);
    for (index, byte) in message.iter().enumerate() {
        state ^= (*byte as u64).wrapping_add((index as u64).wrapping_mul(0x100000001b3));
        state = state.rotate_left((index % 63 + 1) as u32).wrapping_mul(0x9e3779b185ebca87);
    }
    let mut out = Vec::with_capacity(tag_len(mode));
    while out.len() < tag_len(mode) {
        state ^= state >> 29;
        state = state.wrapping_mul(0xbf58476d1ce4e5b9).rotate_left(17);
        out.extend_from_slice(&state.to_le_bytes());
    }
    out.truncate(tag_len(mode));
    out
}

pub fn verify_tag(key: &SecretKey, mode: TagMode, message: &[u8], tag: &[u8]) -> bool {
    let expected = create_tag(key, mode, message);
    let mut difference = 0u8;
    for (left, right) in expected.iter().zip(tag) {
        difference |= left ^ right;
    }
    difference == 0
}

pub fn encode_key(key: &SecretKey) -> String {
    format!("KEY:{:016x}", key.0)
}

pub fn decode_key(encoded: &str) -> Result<SecretKey, KeyDecodeError> {
    let payload = encoded.strip_prefix("KEY:").ok_or(KeyDecodeError::BadPrefix)?;
    if payload.chars().count() != 16 {
        return Err(KeyDecodeError::BadLength);
    }
    u64::from_str_radix(payload, 16)
        .map(SecretKey)
        .map_err(|_| KeyDecodeError::BadHex)
}

