#[path = "solution.rs"]
mod solution;

use solution::{create_tag, decode_key, encode_key, verify_tag, KeyDecodeError, SecretKey, TagMode};

#[test]
fn produces_deterministic_tags_of_each_required_length() {
    let key = SecretKey(0x0123_4567_89ab_cdef);
    let message = b"deterministic message";

    let short_a = create_tag(&key, TagMode::Short, message);
    let short_b = create_tag(&key, TagMode::Short, message);
    let medium = create_tag(&key, TagMode::Medium, message);
    let long = create_tag(&key, TagMode::Long, message);

    assert_eq!(short_a.len(), 8);
    assert_eq!(medium.len(), 16);
    assert_eq!(long.len(), 32);
    assert_eq!(short_a, short_b);
    assert_ne!(short_a, medium[..8]);
    assert_ne!(medium, long[..16]);
}

#[test]
fn tag_depends_on_key_bytes_positions_and_message_length() {
    let base = create_tag(&SecretKey(7), TagMode::Long, &[1, 2, 3]);
    assert_ne!(base, create_tag(&SecretKey(8), TagMode::Long, &[1, 2, 3]));
    assert_ne!(base, create_tag(&SecretKey(7), TagMode::Long, &[1, 9, 3]));
    assert_ne!(base, create_tag(&SecretKey(7), TagMode::Long, &[3, 2, 1]));
    assert_ne!(base, create_tag(&SecretKey(7), TagMode::Long, &[1, 2, 3, 0]));
}

#[test]
fn verification_requires_exact_length_and_exact_content() {
    let key = SecretKey(42);
    let message = b"payload";
    let tag = create_tag(&key, TagMode::Medium, message);
    assert!(verify_tag(&key, TagMode::Medium, message, &tag));

    let mut corrupted = tag.clone();
    corrupted[0] ^= 1;
    corrupted[15] ^= 1;
    assert!(!verify_tag(&key, TagMode::Medium, message, &corrupted));
    assert!(!verify_tag(&key, TagMode::Medium, message, &tag[..15]));

    let mut extended = tag.clone();
    extended.push(0);
    assert!(!verify_tag(&key, TagMode::Medium, message, &extended));
    assert!(!verify_tag(&key, TagMode::Short, message, &tag));
}

#[test]
fn empty_message_and_zero_key_are_valid() {
    let key = SecretKey(0);
    let tag = create_tag(&key, TagMode::Short, &[]);
    assert_eq!(tag.len(), 8);
    assert!(verify_tag(&key, TagMode::Short, &[], &tag));
}

#[test]
fn key_encoding_is_fixed_width_lowercase_hex_and_round_trips() {
    let key = SecretKey(0x00ab_cdef_0123_4567);
    let encoded = encode_key(&key);
    assert_eq!(encoded, "KEY:00abcdef01234567");

    let decoded = decode_key("KEY:00ABCDEF01234567").unwrap();
    assert_eq!(decoded.0, key.0);
    assert_eq!(encode_key(&SecretKey(0)), "KEY:0000000000000000");
    assert_eq!(encode_key(&SecretKey(u64::MAX)), "KEY:ffffffffffffffff");
}

#[test]
fn decoding_distinguishes_prefix_length_and_hex_errors() {
    assert!(matches!(decode_key("BAD:0000000000000000"), Err(KeyDecodeError::BadPrefix)));
    assert!(matches!(decode_key("KEY:123"), Err(KeyDecodeError::BadLength)));
    assert!(matches!(decode_key("KEY:00000000000000000"), Err(KeyDecodeError::BadLength)));
    assert!(matches!(decode_key("KEY:000000000000000g"), Err(KeyDecodeError::BadHex)));
    assert!(matches!(decode_key("KEY:00000000000000é"), Err(KeyDecodeError::BadLength)));
}

